#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// RFC 3550 §5.1, hand-built: version 2, payload type 0 (PCMU), sequence 1, SSRC 0x11223344.
    fn vector() -> Vec<u8> {
        vec![
            0x80, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0xa0, 0x11, 0x22, 0x33, 0x44,
        ]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Rtp);
        let l = p.find_layer(ProtoId::Rtp).unwrap();
        assert_eq!(p.get(l, "version").unwrap(), FieldValue::Uint(2));
        assert_eq!(p.get(l, "padding").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "extension").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "numsync").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "marker").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "payload").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "sequence").unwrap(), FieldValue::Uint(1));
        assert_eq!(p.get(l, "timestamp").unwrap(), FieldValue::Uint(160));
        assert_eq!(p.get(l, "sourcesync").unwrap(), FieldValue::Uint(287454020));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Rtp);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Rtp);
        let l = p.find_layer(ProtoId::Rtp).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Rtp, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
